$targetDir = "stitch_screens"
if (-not (Test-Path $targetDir)) {
    New-Item -ItemType Directory -Path $targetDir | Out-Null
}

foreach ($screen in $screens) {
    Write-Host "Downloading screen $($screen.id): $($screen.name)"
    
    $imgPath = Join-Path $targetDir "$($screen.id)_$($screen.name).png"
    $htmlPath = Join-Path $targetDir "$($screen.id)_$($screen.name).html"
    
    curl.exe -L -o $imgPath $screen.img
    curl.exe -L -o $htmlPath $screen.html
}

Write-Host "All downloads complete!"
